function paraHoraLocal(dataInicioUtc, fusoHorario) {
  const d = new Date(String(dataInicioUtc).replace(' ', 'T') + 'Z');
  const dtf = new Intl.DateTimeFormat('en-US', { timeZone: fusoHorario, hourCycle: 'h23', hour: '2-digit', minute: '2-digit' });
  const p = dtf.formatToParts(d).reduce((acc, x) => { acc[x.type] = x.value; return acc; }, {});
  return p.hour + ':' + p.minute;
}

function formataHora12(dataInicio) {
  const m = String(dataInicio).match(/T?(\d{2}):(\d{2})/);
  if (!m) return '';
  let h = Number(m[1]);
  const mi = m[2];
  const sufixo = h >= 12 ? 'p.m.' : 'a.m.';
  h = h % 12; if (h === 0) h = 12;
  return String(h).padStart(2, '0') + ':' + mi + ' ' + sufixo;
}

const https = require('https');
const vars = $('Variaveis').first().json;

function httpReq(method, url, headers, body) {
  return new Promise((resolve, reject) => {
    const match = url.match(/^https?:\/\/([^/]+)(.*)/); const hostname = match[1]; const path = match[2] || '/';
    const opts = { hostname, path, method, headers: headers || {} };
    const req = https.request(opts, res => {
      let d = '';
      res.on('data', c => d += c);
      res.on('end', () => { try { resolve(JSON.parse(d)); } catch(e) { resolve({ raw: d }); } });
    });
    req.on('error', reject);
    if (body) req.write(typeof body === 'string' ? body : JSON.stringify(body));
    req.end();
  });
}

const resposta = $input.first().json;
const pendentes = resposta.data || [];
const agora = new Date();

const candidatos = pendentes.filter(e => {
  if (e.modo_silencio) return false;
  const inicio = new Date(String(e.data_inicio).replace(' ', 'T') + 'Z');
  const limite = new Date(inicio.getTime() - e.antecedencia_lembrete_min * 60000);
  return agora >= limite;
});

const apiH = { 'X-Internal-Secret': vars.INTERNAL_SECRET };
const textos = {
  'pt-BR': { titulo: 'Lembrete!', prefixo: '\u00e0s' },
  'es-MX': { titulo: '\u00a1Recordatorio!', prefixo: 'a las' }
};
function montaMensagem(e) {
  const t = textos[e.idioma] || textos['es-MX'];
  return '\ud83d\udd14 ' + t.titulo + '\n\n> \ud83d\udccc ' + e.titulo + '\n> \ud83d\udd52 ' + t.prefixo + ' ' + formataHora12(paraHoraLocal(e.data_inicio, e.fuso_horario));
}
const prontos = [];
for (const e of candidatos) {
  const check = await httpReq('GET', vars.BASE_URL + '/api/internal/eventoValido.php?id_evento=' + e.id_evento, apiH);
  if (check.ok && check.data && check.data.valido === false) continue;
  const hora_formatada = formataHora12(paraHoraLocal(e.data_inicio, e.fuso_horario));
  prontos.push({ ...e, hora_formatada, texto_mensagem: montaMensagem(e) });
}

if (!prontos.length) return [];
return prontos.map(e => ({ json: e }));
